local M={}; M.states={IDLE=true,DIALING=true,RINGING_OUT=true,INCOMING=true,CONNECTING=true,CONNECTED=true,DISCONNECTING=true,ENDED=true,FAILED=true}
local t={IDLE={dial="DIALING",incoming="INCOMING"},DIALING={ringing="RINGING_OUT",connected="CONNECTED",failed="FAILED",cancel="DISCONNECTING",hangup="DISCONNECTING"},RINGING_OUT={connected="CONNECTED",failed="FAILED",cancel="DISCONNECTING",hangup="DISCONNECTING",remote_hangup="ENDED",ended="ENDED"},INCOMING={answer="CONNECTING",reject="DISCONNECTING",hangup="DISCONNECTING",remote_hangup="ENDED",ended="ENDED"},CONNECTING={connected="CONNECTED",failed="FAILED",hangup="DISCONNECTING"},CONNECTED={hangup="DISCONNECTING",remote_hangup="DISCONNECTING"},DISCONNECTING={ended="ENDED",remote_hangup="ENDED",failed="FAILED"},ENDED={},FAILED={}}
function M.new(id,direction,now) return {call_id=id,direction=direction,state="IDLE",control_transport="relay",media_transport="relay_pcm",media_backend=nil,start_time=now,connect_time=nil,end_time=nil,generation=1} end
function M.step(c,event,now) local n=t[c.state] and t[c.state][event]; if not n then if (c.state=="ENDED" or c.state=="FAILED") and event=="duplicate" then return true end; return false,"invalid_transition" end; c.state=n; if n=="CONNECTED" then c.connect_time=now end; if n=="ENDED" or n=="FAILED" then c.end_time=now end; return true end
return M
